<script setup lang="ts">
import {ElButton,ElInput,ElInputNumber,ElSelect,ElOption,ElTable,ElTableColumn,ElPagination,vLoading} from 'element-plus'
import {computed,ref,watch} from 'vue'
import {onBeforeRouteLeave} from 'vue-router'
import {confirmAction} from '../../shared/confirm'
import {api,type Account} from '../../api'
import {base,reasonText,type Restaurant,type PageResult} from './types'
import './dining.css'
interface Cost {storeId:string;storeName:string;skuId:string;skuCode:string;productName:string;purchaseCostFen:number|null;unitVersionId:string;revision:number;source:'STORE_OVERRIDE'|'GLOBAL_DEFAULT'|'UNCONFIGURED'}
const props=defineProps<{account:Account}>(),canManage=computed(()=>props.account.permissionCodes.includes('dining.manage'))
const stores=ref<{id:string;name:string}[]>([]),storeId=ref(''),items=ref<Cost[]>([]),drafts=ref<Record<string,number|null>>({}),page=ref(1),total=ref(0),search=ref(''),loading=ref(false),busy=ref(''),error=ref(''),notice=ref('')
const dirty=computed(()=>items.value.some(i=>drafts.value[i.skuId]!== (i.purchaseCostFen===null?null:i.purchaseCostFen/100)))
onBeforeRouteLeave(async()=>!dirty.value||await confirmAction('进货成本尚未保存，确定离开吗？'))
let generation=0
async function initialize(){error.value='';try{const restaurants=(await api<PageResult<Restaurant>>(`${base}/restaurants?pageSize=100`)).items;stores.value=[...new Map(restaurants.flatMap(r=>r.fulfillmentStore?[[r.fulfillmentStore.id,r.fulfillmentStore] as const]:[])).values()];if(!storeId.value&&stores.value.length)storeId.value=stores.value[0]!.id}catch(e){error.value=reasonText(e)}}
async function reload(nextPage=page.value){if(dirty.value&&!await confirmAction('切换查询将丢弃未保存的进货成本，确定继续吗？'))return;page.value=nextPage;await load()}
async function changeStore(id:string){if(dirty.value&&!await confirmAction('切换前置仓将丢弃未保存的进货成本，确定继续吗？'))return;storeId.value=id}
async function load(){const current=++generation;items.value=[];if(!storeId.value)return;loading.value=true;error.value='';try{const result=await api<PageResult<Cost>>(`${base}/purchase-costs?${new URLSearchParams({storeId:storeId.value,page:String(page.value),pageSize:'20',search:search.value.trim()})}`);if(current===generation){items.value=result.items;total.value=result.total;drafts.value=Object.fromEntries(result.items.map(i=>[i.skuId,i.purchaseCostFen===null?null:i.purchaseCostFen/100]))}}catch(e){if(current===generation)error.value=reasonText(e)}finally{if(current===generation)loading.value=false}}
async function save(row:Cost){if(busy.value||!canManage.value)return;const amount=drafts.value[row.skuId];if(amount==null||!Number.isFinite(amount)||amount<0||amount>10000000000){error.value='请输入非负进货价，最多两位小数。';return}const current=generation,preserved=Object.fromEntries(items.value.filter(i=>i.skuId!==row.skuId&&drafts.value[i.skuId]!== (i.purchaseCostFen===null?null:i.purchaseCostFen/100)).map(i=>[i.skuId,drafts.value[i.skuId]??null]));busy.value=row.skuId;error.value='';notice.value='';try{await api(`${base}/purchase-costs`,{method:'PUT',body:JSON.stringify({storeId:storeId.value,skuId:row.skuId,purchaseCostFen:Math.round(amount*100),unitVersionId:row.unitVersionId,revision:row.revision})});if(current!==generation)return;await load();drafts.value={...drafts.value,...preserved};notice.value='本前置仓进货成本已保存，仅影响后续订单的餐饮佣金快照。'}catch(e){if(current===generation)error.value=`${reasonText(e)}；当前输入已保留，请核对最新单位版本后重试。`}finally{busy.value=''}}
watch(storeId,()=>{page.value=1;load()})
watch(()=>[props.account.accountId,props.account.permissionCodes.join(',')],()=>{busy.value='';generation++;items.value=[];storeId.value='';initialize()},{immediate:true})
</script>
<template><section class="page-content dining-page"><header class="page-heading"><div><h1>履约仓进货成本</h1><p>优先使用本前置仓覆盖值，未覆盖时沿用全局默认进货价。保存会创建本仓独立覆盖。</p></div></header><section class="panel"><form class="toolbar" @submit.prevent="reload(1)"><el-select :model-value="storeId" @update:model-value="changeStore" aria-label="履约前置仓" :disabled="!!busy" placeholder="选择前置仓" style="width:220px"><el-option v-for="s in stores" :key="s.id" :value="s.id" :label="s.name"/></el-select><el-input v-model="search" aria-label="成本商品搜索" placeholder="搜索商品名" style="width:240px"/><el-button native-type="submit" :disabled="!storeId||!!busy" :loading="loading">查询</el-button></form><p v-if="error" role="alert" class="error">{{error}} <el-button @click="storeId?reload():initialize()">重试</el-button></p><p v-if="notice" role="status">{{notice}}</p><el-table v-loading="loading" :data="items" empty-text="暂无成本候选，请先创建餐饮店并匹配前置仓"><el-table-column prop="productName" label="商品" min-width="180"/><el-table-column prop="skuCode" label="SKU" min-width="120"/><el-table-column label="当前成本来源" min-width="130"><template #default="{row}">{{({STORE_OVERRIDE:'本仓独立覆盖',GLOBAL_DEFAULT:'全局默认',UNCONFIGURED:'未配置'} as Record<string,string>)[row.source]||row.source}}</template></el-table-column><el-table-column label="进货单价（元/当前销售单位）" min-width="210"><template #default="{row}"><el-input-number v-model="drafts[row.skuId]" :aria-label="`${row.skuCode}进货成本`" :min="0" :max="10000000000" :precision="2" :step="0.01" :disabled="!canManage||!!busy"/></template></el-table-column><el-table-column v-if="canManage" label="操作" width="120"><template #default="{row}"><el-button :loading="busy===row.skuId" :disabled="!!busy&&busy!==row.skuId" @click="save(row as Cost)">保存覆盖</el-button></template></el-table-column></el-table><el-pagination :current-page="page" :total="total" :page-size="20" layout="prev,pager,next,total" @current-change="reload($event)"/></section></section></template>
